# lead-ins for sub-controls quoted from CTRL without one
for k, lead in [('2-2-3-2', '[… بحد أدنى:] '), ('2-2-3-4', '[… بحد أدنى:] '), ('2-5-3-1', '[… بحد أدنى:] '), ('2-9-3-3', '[… بحد أدنى:] '),
                ('2-9-3-2', '[… بحد أدنى:] '), ('4-1-2-1', '[… مع الأطراف الخارجية التي قد تتأثر بإصابتها بيانات الجهة أو الخدمات المقدمة لها بحد أدنى:] '),
                ('4-1-3-1', '[… مع الأطراف الخارجية التي تقدم خدمات الإسناد للأمن السيبراني أو لتقنية المعلومات، أو الخدمات المدارة بحد أدنى:] ')]:
    if not OFF[k].startswith('['):
        OFF[k] = lead + OFF[k]

